import glob,gzip,re,collections
pat=re.compile(r'(?i)[\d\.,]+\s*(?:x\s*10\^?-?\d+\s*)?(?:nM|µM|μM|uM|mM|M|pM|nmol|µmol|umol|mmol|mol/l|ng/ml|µg/ml|ug/ml|mg/ml)\b')
for f in sorted(glob.glob('studies/data/raw/*series_matrix*')):
    c=collections.Counter()
    for l in gzip.open(f,'rt',errors='replace'):
        if l.startswith('!series_matrix_table_begin'): break
        for m in pat.finditer(l):
            s=l[max(0,m.start()-60):m.end()+20]
            c[(l.split('\t')[0],s)]+=1
    print('=====',f)
    for k,v in c.items(): print(v,k)

